#include <stdio.h>

#define MAXN 100005

long long tree[MAXN];
int values[MAXN];

void add(int n, int index, long long delta) {
    while (index <= n) {
        tree[index] += delta;
        index += index & -index;
    }
}

long long prefix_sum(int index) {
    long long sum = 0;
    while (index > 0) {
        sum += tree[index];
        index -= index & -index;
    }
    return sum;
}

int main(void) {
    int n, q;
    scanf("%d %d", &n, &q);

    for (int i = 1; i <= n; i++) {
        scanf("%d", &values[i]);
        add(n, i, values[i]);
    }

    for (int i = 0; i < q; i++) {
        int type, k;
        scanf("%d %d", &type, &k);

        if (type == 0) {
            int p;
            scanf("%d", &p);
            add(n, k, (long long)p - values[k]);
            values[k] = p;
        } else {
            printf("%lld\n", prefix_sum(k));
        }
    }

    return 0;
}
